const state={n:20,admin:true,selected:0,empty:false,email:false};let picked=new Set();const $=s=>document.querySelector(s);function draw(){const q=$('#search').value.trim();$('.reason').hidden=!state.admin;$('.search-box').hidden=state.email;$('#member-tab').classList.toggle('on',!state.email);$('#email-tab').classList.toggle('on',state.email);$('#member-tab').setAttribute('aria-pressed',!state.email);$('#email-tab').setAttribute('aria-pressed',state.email);$('#count').textContent=picked.size?`선택 ${picked.size}명`:'선택 없음 · 나중에 초대해도 돼요';$('.chips').innerHTML=[...picked].map(i=>`<button data-remove="${i}" aria-label="가상 회원 ${i+1} 선택 취소">가상 회원 ${i+1} ×</button>`).join('');const ids=Array.from({length:state.n},(_,i)=>i).filter(i=>!state.empty&&(!q||`가상 회원 ${i+1}`.includes(q)||q===`sc${i+1}@example.test`));$('.panel-title').textContent=state.email?'입력한 이메일 목록':`회원 ${ids.length}명 · 선택 ${picked.size}명`;$('.list').innerHTML=state.email?'<label>비회원 이메일<textarea aria-label="비회원 이메일" class="email-entry" placeholder="이메일을 한 줄에 하나씩 입력해 주세요"></textarea></label><div class="email-results"><p class="empty">입력한 이메일이 없어요.</p></div>':ids.map(i=>`<label class="row"><span class="avatar" aria-hidden="true">가</span><span class="identity">가상 회원 ${String(i+1).padStart(2,'0')}<small>sc***@gmail.com</small></span><span class="check-target"><input type="checkbox" data-id="${i}" aria-label="가상 회원 ${i+1} 선택" ${picked.has(i)?'checked':''}></span></label>`).join('')||'<p class="empty">'+(state.empty||q?'검색 결과가 없어요.':'등록된 회원이 없어요. 나중에 초대해도 돼요.')+'</p>'; }function setState(s){Object.assign(state,s);picked=new Set(Array.from({length:state.selected},(_,i)=>i));draw();document.querySelector('main').scrollTop=0}window.setState=setState;window.addEventListener('message',e=>{if(e.data?.type==='sdd280-state')setState(e.data.state)});$('.list').addEventListener('change',e=>{if(e.target.dataset.id!==undefined){let i=+e.target.dataset.id;e.target.checked?picked.add(i):picked.delete(i);draw();document.querySelector(`[data-id="${i}"]`)?.focus({preventScroll:true})}});$('.list').addEventListener('input',e=>{if(e.target.classList.contains('email-entry')){const entries=e.target.value.split(/\n|,/).map(x=>x.trim()).filter(Boolean);$('.email-results').textContent=entries.length?entries.join(' · '):'입력한 이메일이 없어요。'}});$('.chips').onclick=e=>{if(e.target.dataset.remove!==undefined){picked.delete(+e.target.dataset.remove);draw()}};$('#search').oninput=draw;$('#member-tab').onclick=()=>{state.email=false;draw()};$('#email-tab').onclick=()=>{state.email=true;draw()};draw();
function fitSticky(){const m=document.querySelector("main"),l=document.querySelector(".left");l.style.position=innerWidth>=1024&&l.offsetHeight+24<m.clientHeight?"sticky":"static"}new ResizeObserver(fitSticky).observe(document.querySelector(".left"));window.addEventListener("resize",fitSticky);fitSticky();

document.querySelector('main').addEventListener('focusin',e=>{const m=document.querySelector('main'),t=e.target.closest('.row')||e.target;const r=t.getBoundingClientRect(),b=m.getBoundingClientRect();if(r.bottom>b.bottom-8)m.scrollTop+=r.bottom-b.bottom+8;else if(r.top<b.top+8)m.scrollTop+=r.top-b.top-8;});
